+    env["GIT_AUTHOR_EMAIL"] = "t@e.com"
+    env["GIT_COMMITTER_NAME"] = "T"
+    env["GIT_COMMITTER_EMAIL"] = "t@e.com"
+    env["PATH"] = ShellEnvironment.path()
+    p.environment = env
+    let pipe = Pipe()
+    p.standardOutput = pipe
+    p.standardError = pipe
+    try? p.run()
